/**
 * ATHENA TOOLS HUB — database types (hand-written to match
 * supabase/migrations/0001_core.sql).
 *
 * These are NOT generated by supabase CLI; they are the authoritative local
 * mirror of the schema. If a migration changes the schema, update this file.
 */

// ---------------------------------------------------------------------------
// Enums (match the Postgres enum types in 0001_core.sql)
// ---------------------------------------------------------------------------

export type OrgMemberRole =
  | 'owner'
  | 'admin'
  | 'member'
  | 'viewer';

/** Honest tool lifecycle — never 'connected'/'operational-tested' without a real test. */
export type ToolState =
  | 'cataloged'
  | 'needs-config'
  | 'in-development'
  | 'connected'
  | 'operational-tested'
  | 'error'
  | 'unavailable';

export type IntegrationType = 'mcp' | 'cli' | 'api' | 'webhook' | 'sdk';

export type JobState =
  | 'CREATED'
  | 'VALIDATING'
  | 'PENDING_APPROVAL'
  | 'QUEUED'
  | 'RUNNING'
  | 'COMPLETED'
  | 'FAILED'
  | 'CANCELLED';

export type ApprovalStatus =
  | 'pending'
  | 'approved'
  | 'rejected'
  | 'expired'
  | 'cancelled';

export type ActorType = 'user' | 'api_key' | 'system';

// ---------------------------------------------------------------------------
// Row types
// ---------------------------------------------------------------------------

export interface Organization {
  id: string;
  name: string;
  slug: string;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

export interface OrganizationMember {
  id: string;
  org_id: string;
  user_id: string;
  role: OrgMemberRole;
  created_at: string;
  updated_at: string;
}

export interface Tool {
  id: string;
  org_id: string;
  slug: string;
  name: string;
  description: string | null;
  category: string | null;
  state: ToolState;
  license: string | null;
  license_verified: boolean;
  repo_url: string | null;
  website_url: string | null;
  config: Record<string, unknown>;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

export interface ToolCapability {
  id: string;
  org_id: string;
  tool_id: string;
  name: string;
  description: string | null;
  input_schema: Record<string, unknown>;
  output_schema: Record<string, unknown>;
  created_at: string;
}

export interface Integration {
  id: string;
  org_id: string;
  name: string;
  provider: string;
  type: IntegrationType;
  state: ToolState;
  /** Non-secret config only — secrets belong to the vault, never here. */
  config: Record<string, unknown>;
  last_test_at: string | null;
  last_test_result: {
    ok: boolean;
    latency_ms?: number;
    checked_at?: string;
    error?: string;
  } | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

export interface ExecutionJob {
  id: string;
  org_id: string;
  tool_id: string | null;
  integration_id: string | null;
  /** Unique per org — safe retries, no double execution. */
  idempotency_key: string;
  state: JobState;
  params: Record<string, unknown>;
  result: Record<string, unknown> | null;
  error: { code?: string; message?: string; details?: unknown } | null;
  /** 0..100 */
  progress: number;
  started_at: string | null;
  finished_at: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

export interface ExecutionEvent {
  id: string;
  job_id: string;
  org_id: string;
  type: string;
  message: string | null;
  payload: Record<string, unknown>;
  created_at: string;
}

export interface ApprovalRequest {
  id: string;
  org_id: string;
  job_id: string | null;
  title: string;
  payload: Record<string, unknown>;
  requested_by: string | null;
  status: ApprovalStatus;
  decided_by: string | null;
  decision_justification: string | null;
  decided_at: string | null;
  expires_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface GeneratedAsset {
  id: string;
  org_id: string;
  job_id: string | null;
  kind: string;
  name: string;
  file_path: string | null;
  mime_type: string | null;
  size_bytes: number | null;
  metadata: Record<string, unknown>;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

export interface UsageRecord {
  id: string;
  org_id: string;
  job_id: string | null;
  tool_id: string | null;
  kind: string;
  quantity: number;
  unit: string | null;
  /** Cost in minor currency units (cents). */
  cost_cents: number;
  currency: string;
  recorded_at: string;
  created_at: string;
}

export interface AuditLog {
  id: string;
  org_id: string;
  actor_user_id: string | null;
  actor_type: ActorType;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  diff: { before?: unknown; after?: unknown } | Record<string, unknown> | null;
  created_at: string;
}

// ---------------------------------------------------------------------------
// Insert / Update helpers
// ---------------------------------------------------------------------------

export type Tables = {
  organizations: Organization;
  organization_members: OrganizationMember;
  tools: Tool;
  tool_capabilities: ToolCapability;
  integrations: Integration;
  execution_jobs: ExecutionJob;
  execution_events: ExecutionEvent;
  approval_requests: ApprovalRequest;
  generated_assets: GeneratedAsset;
  usage_records: UsageRecord;
  audit_logs: AuditLog;
};

export type TableName = keyof Tables;

export type RowInsert<T extends TableName> = {
  [K in keyof Tables[T] as K extends 'id' | 'created_at' | 'updated_at' ? never : K]: Tables[T][K];
} & {
  [K in keyof Tables[T] as K extends 'id' | 'created_at' | 'updated_at' ? K : never]?: Tables[T][K];
};

export type RowUpdate<T extends TableName> = {
  [K in keyof Tables[T] as K extends 'id' | 'created_at' ? never : K]?: Tables[T][K];
};

/** Minimal Database shape so supabase-js clients stay typed. */
export interface Database {
  public: {
    Tables: {
      [K in TableName]: {
        Row: Tables[K];
        Insert: RowInsert<K>;
        Update: RowUpdate<K>;
      };
    };
  };
}
